protocol TextAccess { var words: [String] { get } }

private var spellKey: UInt8 = 0
extension NSString: TextAccess {                 // existing class, untouched
    var words: [String] { components(separatedBy: .whitespaces) }
}
extension NSString {                             // stored state, attached
    var spellState: SpellState? {
        get { objc_getAssociatedObject(self, &spellKey) as? SpellState }
        set { objc_setAssociatedObject(self, &spellKey, newValue, .OBJC_ASSOCIATION_RETAIN) }
    }
}
